  async function updateOpportunity(event: React.FormEvent<HTMLFormElement>) { event.preventDefault(); if (!editingOpportunity) return; if (!can(["sales", "admin"])) return notify("Demo role นี้ไม่มีสิทธิ์แก้ไข Opportunity", "warning"); setLoading(true); const data = new FormData(event.currentTarget); const parsed = opportunitySchema.safeParse(Object.fromEntries(data)); const productIds = data.getAll("productIds").map(String); const productQuantities = Object.fromEntries(productIds.map(product_id => [product_id, Math.max(0.01, Number(data.get(`quantity_${product_id}`)) || 1)])); if (!parsed.success || productIds.length === 0) { notify("กรุณากรอกข้อมูลและเลือกสินค้าอย่างน้อย 1 รายการ", "warning"); setLoading(false); return; } const confirmation = await Swal.fire({ title: text(language, "ยืนยันการแก้ไข?", "Confirm changes?"), text: editingOpportunity.name, icon: "question", showCancelButton: true, confirmButtonText: text(language, "บันทึกการแก้ไข", "Save changes"), cancelButtonText: text(language, "ยกเลิก", "Cancel"), confirmButtonColor: "#2d83df" }); if (!confirmation.isConfirmed) { setLoading(false); return; } const updated: Opportunity = { ...editingOpportunity, name: parsed.data.name, customer: parsed.data.customer, value: parsed.data.value, source: parsed.data.source, segment: parsed.data.segment, productIds, productQuantities }; try { if (supabase) { const result = await supabase.from("opportunities").update({ name: updated.name, customer_name: updated.customer, expected_value: updated.value, lead_source: updated.source, project_segment: updated.segment, updated_at: new Date().toISOString() }).eq("id", updated.id); if (result.error) throw result.error; const remove = await supabase.from("opportunity_products").delete().eq("opportunity_id", updated.id); if (remove.error) throw remove.error; const links = await supabase.from("opportunity_products").insert(productIds.map(product_id => ({ opportunity_id: updated.id, product_id, quantity: productQuantities[product_id] }))); if (links.error) throw links.error; } setOpportunities(current => current.map(item => item.id === updated.id ? updated : item)); setShowOpportunityForm(false); setEditingOpportunity(null); if (opportunityEditId) router.push(`/opportunities/${updated.id}`); notify("แก้ไข Opportunity แล้ว"); } catch (error) { notify(`แก้ไขไม่สำเร็จ: ${error instanceof Error ? error.message : "Supabase error"}`, "error"); } finally { setLoading(false); } }
  async function createQuotation(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault(); if (!can(["sales", "admin"])) return notify("Demo role นี้ไม่มีสิทธิ์สร้างใบเสนอราคา"); setLoading(true);
    const data = new FormData(event.currentTarget); const parsed = quotationSchema.safeParse(Object.fromEntries(data)); const items = data.getAll("productIds").map(String).map(id => { const product = products.find(item => item.id === id); return { product, quantity: Number(data.get(`quantity_${id}`)), unitPrice: Number(data.get(`price_${id}`)) }; }).filter(item => item.product && item.quantity > 0 && item.unitPrice >= 0);
    if (!parsed.success || items.length === 0) { notify("กรุณาเลือกสินค้าอย่างน้อย 1 รายการ และกรอกจำนวน/ราคาให้ถูกต้อง", "warning"); setLoading(false); return; }
    const opportunityRow = opportunities.find(item => item.name === parsed.data.opportunity || item.id === parsed.data.opportunity)
      ?? opportunities.find(item => item.id === opportunityDetailId);
    const supplier = suppliers.find(item => item.name.trim().toLowerCase() === "kc");
    if (!opportunityRow) { notify("ไม่พบ Opportunity ที่เลือก กรุณาปิดแล้วเปิดใบเสนอราคาใหม่จาก Opportunity", "error"); setLoading(false); return; }
    if (!supplier) { notify("ไม่พบ Supplier KC ในฐานข้อมูล กรุณารัน migration 20260928000300_ensure_kc_supplier.sql ใน Supabase", "error"); setLoading(false); return; }
    const merchandise = items.reduce((sum, item) => sum + item.quantity * item.unitPrice, 0);
    const cutting = Number(data.get("cuttingFee")) || 0;
    const pricing = calculatePricing({ quantity: 1, unitPrice: merchandise, cuttingFee: cutting, discountAmount: parsed.data.discount, shipping: parsed.data.shipping });
    const quotationItems: QuotationItem[] = items.map(item => ({ productId: item.product?.id, productName: item.product?.name ?? "", quantity: item.quantity, unitPrice: item.unitPrice, cuttingFee: 0, lineTotal: item.quantity * item.unitPrice }));
    const supplierItems = items.map(item => ({ productId: item.product!.id, productName: item.product!.name, quantity: item.quantity, unitPrice: item.product!.supplierPrice, lineTotal: item.quantity * item.product!.supplierPrice }));
    const supplierSubtotal = supplierItems.reduce((sum, item) => sum + item.lineTotal, 0);
    const supplierVat = Math.round(supplierSubtotal * 0.07 * 100) / 100;
    const taxMode = document.querySelector<HTMLSelectElement>(".quotation-tax-mode")?.value === "inclusive" ? "inclusive" : "exclusive";
    const row: Quotation = { id: crypto.randomUUID(), number: `QT-${Date.now()}`, opportunity: opportunityRow.name, customer: opportunityRow.customer, amount: pricing.total, cuttingFee: cutting, subtotal: pricing.subtotal, discount: parsed.data.discount, shipping: pricing.shipping, vat: pricing.vat, taxMode, status: "Draft", sync: "Pending", productName: quotationItems.map(item => item.productName).join(", "), quantity: quotationItems.reduce((sum, item) => sum + item.quantity, 0), unitPrice: quotationItems[0]?.unitPrice, items: quotationItems };
    const supplierRow: SupplierQuotation = { id: crypto.randomUUID(), number: `SQ-${Date.now()}`, quotationId: row.id, opportunityId: opportunityRow.id, opportunity: opportunityRow.name, supplierId: supplier.id, supplier: supplier.name, subtotal: supplierSubtotal, vat: supplierVat, amount: supplierSubtotal + supplierVat, status: "Received", items: supplierItems };
    try {
      if (!supabase) throw new Error("Supabase is not configured");
      const result = await supabase.rpc("create_linked_quotations", {
        p_customer_quotation: { id: row.id, quotation_number: row.number, opportunity_id: opportunityRow.id, opportunity_name: row.opportunity, customer_name: row.customer, subtotal: pricing.subtotal, discount: parsed.data.discount, shipping: pricing.shipping, vat: pricing.vat, total_amount: row.amount, status: row.status, sync_status: row.sync, tax_mode: taxMode },
        p_customer_items: quotationItems.map(item => ({ product_id: item.productId, product_name: item.productName, quantity: item.quantity, unit_price: item.unitPrice, cutting_fee: item.cuttingFee, line_total: item.lineTotal, specification: { category: products.find(product => product.id === item.productId)?.category ?? "" } })),
        p_supplier_quotation: { id: supplierRow.id, quotation_number: supplierRow.number, opportunity_id: supplierRow.opportunityId, opportunity_name: supplierRow.opportunity, supplier_id: supplierRow.supplierId, supplier_name: supplierRow.supplier, subtotal: supplierRow.subtotal, vat: supplierRow.vat, total_amount: supplierRow.amount, status: supplierRow.status },
        p_supplier_items: supplierItems.map(item => ({ product_id: item.productId, product_name: item.productName, quantity: item.quantity, unit_price: item.unitPrice, line_total: item.lineTotal })),
      });
      if (result.error) throw result.error;
      await supabase.from("sync_logs").insert({ document_type: "Quotation", document_id: row.id, document_number: row.number, status: row.sync });
      setQuotations(current => [row, ...current]); setSupplierQuotations(current => [supplierRow, ...current]);
      setShowQuotationForm(false); setQuotationOpportunity(undefined);
      notify(`สร้าง ${row.number} และ ${supplierRow.number} โดยอ้างอิงถึงกันแล้ว`);
    } catch (error) { notify(`บันทึกเอกสารคู่ไม่สำเร็จ: ${error instanceof Error ? error.message : "ตรวจสอบ migration, Supabase และ RLS"}`, "error"); }
    finally { setLoading(false); }
  }
